// Normalize input: webhook (push payload) vs schedule (poll)
// sync.yaml controls which files get processed — no zone filter here
let webhookData = null;
try { webhookData = $('Webhook').first()?.json?.body; } catch {}
const isWebhook = !!webhookData;

if (isWebhook) {
  const commits = webhookData.commits || [];
  const repo = webhookData.repository?.full_name || $env.GIT_SYNC_REPO;
  const ref = webhookData.ref || '';

  if (ref && !ref.endsWith('/main') && !ref.endsWith('/master')) {
    return [{ json: { mode: 'webhook', repo, skipped: true, reason: `Non-default branch: ${ref}` } }];
  }

  const isSyncCommit = (msg) => msg.startsWith('[sync]') && !msg.startsWith('[sync-');
  const allSync = commits.length > 0 && commits.every(c => isSyncCommit(c.message || ''));
  if (allSync) {
    return [{ json: { mode: 'webhook', repo, skipped: true, reason: 'All commits are [sync] \u2014 skipping to prevent loop' } }];
  }

  const nonSyncCommits = commits.filter(c => !isSyncCommit(c.message || ''));

  // Collect changed .md and .pdf files — NO zone filter, sync.yaml controls matching
  let changed = new Set();
  let removed = new Set();
  for (const commit of nonSyncCommits) {
    for (const f of (commit.added || [])) { if (f.endsWith('.md') || f.endsWith('.pdf')) changed.add(f); }
    for (const f of (commit.modified || [])) { if (f.endsWith('.md') || f.endsWith('.pdf')) changed.add(f); }
    for (const f of (commit.removed || [])) { if (f.endsWith('.md') || f.endsWith('.pdf')) { removed.add(f); changed.delete(f); } }
  }

  const syncYamlChanged = [...changed].includes('sync.yaml') || [...removed].includes('sync.yaml');

  return [{ json: { mode: 'webhook', repo, changed: [...changed], removed: [...removed], sync_yaml_changed: syncYamlChanged } }];
} else {
  return [{ json: { mode: 'poll', repo: $env.GIT_SYNC_REPO } }];
}

const https = require('https');
const http = require('http');
const { execSync } = require('child_process');

const input = $input.first().json;
const mode = input.mode;
const repo = input.repo || $env.GIT_SYNC_REPO;
const GITHUB_TOKEN = $env.GITHUB_TOKEN;
const LITELLM_KEY = $env.LITELLM_MASTER_KEY;
const AGENT_ID = 'pm-assistant';

if (input.skipped) {
  return [{ json: { success: true, skipped: true, reason: input.reason } }];
}

// --- Concurrency lock ---
const execId = Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
const lockSql = `INSERT INTO execution_locks (workflow_id, locked_at, execution_id) VALUES (19, NOW(), '${execId}') ON CONFLICT (workflow_id) DO UPDATE SET locked_at = NOW(), execution_id = '${execId}' WHERE execution_locks.locked_at < NOW() - interval '10 minutes' RETURNING workflow_id`;
const lockResult = (await dbQuery(lockSql)).trim();
if (!lockResult.startsWith('19')) {
  return [{ json: { success: true, skipped: true, reason: 'Another WF19 execution in progress' } }];
}

// --- HTTP helper ---
function httpReq(options, postData) {
  return new Promise((resolve, reject) => {
    const lib = options.protocol === 'https:' ? https : http;
    const req = lib.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => body += chunk);
      res.on('end', () => {
        try { resolve({ status: res.statusCode, data: JSON.parse(body) }); }
        catch { resolve({ status: res.statusCode, data: body }); }
      });
    });
    req.on('error', reject);
    req.setTimeout(60000, () => { req.destroy(); reject(new Error('timeout')); });
    if (postData) req.write(postData);
    req.end();
  });
}

// --- GitHub API helper ---
async function ghApi(path, method, body) {
  const options = {
    hostname: 'api.github.com',
    port: 443,
    protocol: 'https:',
    path,
    method: method || 'GET',
    headers: {
      'Authorization': `Bearer ${GITHUB_TOKEN}`,
      'User-Agent': 'n8n-git-sync',
      'Accept': 'application/vnd.github.v3+json'
    }
  };
  if (body) {
    const data = JSON.stringify(body);
    options.headers['Content-Type'] = 'application/json';
    options.headers['Content-Length'] = Buffer.byteLength(data);
    return httpReq(options, data);
  }
  return httpReq(options);
}

// --- Docker exec psql helper ---
async function dbQuery(sql) {
  const execData = JSON.stringify({
    Cmd: ['sh', '-c', `PGPASSWORD=$POSTGRES_PASSWORD psql -U sovereign -d gilbert -t -A -c "${sql.replace(/"/g, '\\"')}"`],
    AttachStdout: true, AttachStderr: true, Tty: false
  });
  const execCreate = await httpReq({
    socketPath: '/var/run/docker.sock',
    path: '/v1.41/containers/sovereign-stack-postgres-1/exec',
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(execData) }
  }, execData);
  if (!execCreate.data?.Id) return '';
  const startData = JSON.stringify({ Detach: false, Tty: false });
  const rawResult = await new Promise((resolve, reject) => {
    const req = http.request({
      socketPath: '/var/run/docker.sock',
      path: `/v1.41/exec/${execCreate.data.Id}/start`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(startData) }
    }, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => resolve(Buffer.concat(chunks)));
    });
    req.on('error', reject);
    req.setTimeout(30000, () => { req.destroy(); reject(new Error('timeout')); });
    req.write(startData);
    req.end();
  });
  let text = '';
  let offset = 0;
  while (offset + 8 <= rawResult.length) {
    const frameSize = rawResult.readUInt32BE(offset + 4);
    offset += 8;
    if (frameSize > 0 && offset + frameSize <= rawResult.length) {
      text += rawResult.slice(offset, offset + frameSize).toString('utf8');
      offset += frameSize;
    } else { break; }
  }
  if (!text && rawResult.length > 8) {
    text = rawResult.toString('utf8').replace(/[\x00-\x08]/g, '');
  }
  return text.trim();
}

// --- Load prompt from DB ---
async function loadPrompt(key) {
  return new Promise((resolve) => {
    const req = http.get(
      'http://127.0.0.1:5678/webhook/prompt-server?key=' + encodeURIComponent(key),
      res => {
        let data = '';
        res.on('data', c => data += c);
        res.on('end', () => {
          try { const p = JSON.parse(data); resolve(p.success ? p.content : null); }
          catch { resolve(null); }
        });
      }
    );
    req.on('error', () => resolve(null));
    req.setTimeout(5000, () => { req.destroy(); resolve(null); });
  });
}

// --- Embed text via LiteLLM ---
async function embed(text) {
  const data = JSON.stringify({ model: 'mistral-embed', input: text.substring(0, 8000) });
  const result = await httpReq({
    hostname: 'litellm',
    port: 4000,
    path: '/v1/embeddings',
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${LITELLM_KEY}`,
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(data)
    }
  }, data);
  if (result.data?.data?.[0]?.embedding) {
    return result.data.data[0].embedding;
  }
  return null;
}

// --- Store in Qdrant ---
async function qdrantUpsert(id, vector, payload) {
  const data = JSON.stringify({ points: [{ id, vector, payload }] });
  return httpReq({
    hostname: 'qdrant',
    port: 6333,
    path: '/collections/knowledge/points',
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) }
  }, data);
}

// --- Delete from Qdrant ---
async function qdrantDelete(ids) {
  if (!ids || ids.length === 0) return;
  const data = JSON.stringify({ points: ids });
  return httpReq({
    hostname: 'qdrant',
    port: 6333,
    path: '/collections/knowledge/points/delete',
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) }
  }, data);
}

// --- UUID v4 generator ---
function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

// --- Chunk text for embedding ---
function chunkText(text, maxLen = 1500, overlap = 200) {
  if (text.length <= maxLen) return [text];
  const chunks = [];
  let start = 0;
  while (start < text.length) {
    chunks.push(text.substring(start, start + maxLen));
    start += maxLen - overlap;
  }
  return chunks;
}

// --- Content hash ---
function contentHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const chr = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + chr;
    hash |= 0;
  }
  return 'h' + Math.abs(hash).toString(36) + '_' + str.length;
}

// --- Derive title from markdown ---
function deriveTitle(content, filePath) {
  const h1Match = content.match(/^#\s+(.+)$/m);
  if (h1Match) return h1Match[1].trim().substring(0, 100);
  const parts = filePath.split('/');
  const filename = parts[parts.length - 1].replace(/\.(md|pdf)$/, '');
  return filename.replace(/[-_]/g, ' ').replace(/\b\w/g, l => l.toUpperCase()).substring(0, 100);
}

// --- Extract PDF text via pdftotext ---
function extractPdfFromUrl(filePath, repoName, token) {
  const tmpPdf = '/tmp/sync_' + Date.now() + '.pdf';
  const tmpTxt = tmpPdf + '.txt';
  try {
    const encodedPath = filePath.split('/').map(p => encodeURIComponent(p)).join('/');
    const rawUrl = `https://raw.githubusercontent.com/${repoName}/main/${encodedPath}`;
    const wgetCmd = `/usr/bin/wget -q --header="Authorization: token ${token}" -O "${tmpPdf}" "${rawUrl}"`;
    const fullCmd = `${wgetCmd} && /usr/bin/stat -c %s "${tmpPdf}" && /usr/bin/pdftotext "${tmpPdf}" "${tmpTxt}" && /bin/cat "${tmpTxt}"`;
    const output = execSync(fullCmd, { timeout: 180000, maxBuffer: 20 * 1024 * 1024 });
    const text = output.toString('utf8');
    const firstNewline = text.indexOf('\n');
    const pdfText = text.substring(firstNewline + 1);
    if (!pdfText || pdfText.trim().length === 0) {
      return '[PDF extraction failed: pdftotext returned empty text]';
    }
    return pdfText;
  } catch (e) {
    return '[PDF extraction failed]';
  } finally {
    try { execSync(`/bin/rm -f "${tmpPdf}" "${tmpTxt}"`, { timeout: 5000 }); } catch {}
  }
}

// --- LLM call for personality generation ---
async function llmCall(prompt, systemPrompt) {
  const data = JSON.stringify({
    model: 'fast-summary',
    messages: [
      { role: 'system', content: systemPrompt || 'You are a concise technical writer.' },
      { role: 'user', content: prompt }
    ],
    max_tokens: 4000
  });
  const result = await httpReq({
    hostname: 'litellm',
    port: 4000,
    path: '/v1/chat/completions',
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${LITELLM_KEY}`,
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(data)
    }
  }, data);
  return result.data?.choices?.[0]?.message?.content || '';
}

// --- Parse sync.yaml (simple YAML parser for our known structure) ---
function parseSyncYaml(yamlText) {
  const config = { embed: { include: [], exclude: [] }, personality: { sources: [], max_context_chars: 50000, priority_order: [] } };
  let section = null;
  let subsection = null;
  for (const line of yamlText.split('\n')) {
    const trimmed = line.trim();
    if (trimmed.startsWith('#') || trimmed === '') continue;
    if (trimmed === 'embed:') { section = 'embed'; subsection = null; continue; }
    if (trimmed === 'personality:') { section = 'personality'; subsection = null; continue; }
    if (trimmed === 'confluence:') { section = 'confluence'; subsection = null; continue; }
    if (section === 'embed' && trimmed === 'include:') { subsection = 'include'; continue; }
    if (section === 'embed' && trimmed === 'exclude:') { subsection = 'exclude'; continue; }
    if (section === 'personality' && trimmed === 'sources:') { subsection = 'sources'; continue; }
    if (section === 'personality' && trimmed === 'priority_order:') { subsection = 'priority_order'; continue; }
    if (section === 'personality' && trimmed.startsWith('max_context_chars:')) {
      config.personality.max_context_chars = parseInt(trimmed.split(':')[1].trim()) || 50000;
      continue;
    }
    if (trimmed.startsWith('- ')) {
      const val = trimmed.substring(2).trim().replace(/^["']|["']$/g, '');
      if (section === 'embed' && subsection === 'include') config.embed.include.push(val);
      if (section === 'embed' && subsection === 'exclude') config.embed.exclude.push(val);
      if (section === 'personality' && subsection === 'sources') config.personality.sources.push(val);
      if (section === 'personality' && subsection === 'priority_order') config.personality.priority_order.push(val);
    }
  }
  return config;
}

// --- Glob pattern matcher ---
function globMatch(pattern, filePath) {
  let regex = pattern
    .replace(/\./g, '\\.')
    .replace(/\*\*/g, '\x00DOUBLESTAR\x00')
    .replace(/\*/g, '[^/]*')
    .replace(/\x00DOUBLESTAR\x00/g, '.*');
  regex = '^' + regex + '$';
  try {
    return new RegExp(regex).test(filePath);
  } catch {
    return false;
  }
}

function matchesEmbedConfig(filePath, syncConfig) {
  const included = syncConfig.embed.include.some(p => globMatch(p, filePath));
  if (!included) return false;
  const excluded = syncConfig.embed.exclude.some(p => globMatch(p, filePath));
  return !excluded;
}

function matchesPersonalitySources(filePath, syncConfig) {
  return syncConfig.personality.sources.some(p => globMatch(p, filePath));
}

// ========== MAIN LOGIC ==========

let changed = [];
let removed = [];
const results = { synced: [], deleted: [], skipped_no_match: [], errors: [], personality_rebuilt: false };

// --- Fetch sync.yaml from GitHub ---
let syncConfig;
try {
  const yamlResp = await ghApi(`/repos/${repo}/contents/sync.yaml?ref=main`);
  if (yamlResp.status !== 200) {
    await dbQuery("DELETE FROM execution_locks WHERE workflow_id = 19");
    return [{ json: { success: false, error: 'sync.yaml not found in repo' } }];
  }
  const yamlText = Buffer.from(yamlResp.data.content, 'base64').toString('utf8');
  syncConfig = parseSyncYaml(yamlText);
} catch (e) {
  await dbQuery("DELETE FROM execution_locks WHERE workflow_id = 19");
  return [{ json: { success: false, error: 'Failed to parse sync.yaml' } }];
}

if (mode === 'webhook') {
  changed = input.changed || [];
  removed = input.removed || [];
} else {
  // Poll mode: get full tree from GitHub, compare with sync_state
  try {
    const treeResp = await ghApi(`/repos/${repo}/git/trees/main?recursive=1`);
    if (treeResp.status !== 200) {
      await dbQuery("DELETE FROM execution_locks WHERE workflow_id = 19");
      return [{ json: { success: false, error: 'GitHub tree API failed' } }];
    }
    const tree = treeResp.data.tree || [];
    // All syncable files (md/pdf) — no zone filter, sync.yaml controls matching
    const syncableFiles = tree.filter(t => t.type === 'blob' && (t.path.endsWith('.md') || t.path.endsWith('.pdf')));

    // Load current sync_state — exclude folder rows
    const syncRows = await dbQuery(
      `SELECT file_path, file_sha FROM sync_state WHERE repo = '${repo.replace(/'/g, "''")}' AND (is_folder = false OR is_folder IS NULL)`
    );
    const syncMap = {};
    if (syncRows) {
      for (const row of syncRows.split('\n')) {
        if (!row.trim()) continue;
        const [fp, sha] = row.split('|');
        if (fp) syncMap[fp] = sha;
      }
    }

    for (const f of syncableFiles) {
      if (!syncMap[f.path] || syncMap[f.path] !== f.sha) {
        changed.push(f.path);
      }
    }

    // Detect removed files that were previously tracked
    const currentPaths = new Set(syncableFiles.map(f => f.path));
    for (const fp of Object.keys(syncMap)) {
      if (!currentPaths.has(fp)) {
        removed.push(fp);
      }
    }
  } catch (e) {
    await dbQuery("DELETE FROM execution_locks WHERE workflow_id = 19");
    return [{ json: { success: false, error: 'Poll failed' } }];
  }
}

// Skip README.md, .gitkeep, and sync.yaml itself
changed = changed.filter(f => f !== 'README.md' && !f.endsWith('.gitkeep') && f !== 'sync.yaml');
removed = removed.filter(f => f !== 'README.md' && !f.endsWith('.gitkeep') && f !== 'sync.yaml');

if (changed.length === 0 && removed.length === 0) {
  await dbQuery("DELETE FROM execution_locks WHERE workflow_id = 19");
  return [{ json: { success: true, mode, repo, message: 'No changes to sync', synced: 0, deleted: 0 } }];
}

let personalitySourceChanged = false;

// --- Process changed files ---
for (const filePath of changed) {
  try {
    // Check if file matches sync.yaml embed patterns
    if (!matchesEmbedConfig(filePath, syncConfig)) {
      results.skipped_no_match.push(filePath);
      continue;
    }

    // Check sync_lock (skip if recently synced from Outline direction)
    const lockRow = await dbQuery(
      `SELECT sync_lock, sync_origin FROM sync_state WHERE repo = '${repo.replace(/'/g, "''")}' AND file_path = '${filePath.replace(/'/g, "''")}'`
    );
    if (lockRow && lockRow.trim()) {
      const [lockTime, lockOrigin] = lockRow.split('|');
      if (lockOrigin === 'outline' && lockTime) {
        const lockAge = Date.now() - new Date(lockTime).getTime();
        if (lockAge < 30000) {
          results.synced.push({ file: filePath, skipped: true, reason: 'sync_lock active (Outline origin)' });
          continue;
        }
      }
    }

    const isPdf = filePath.endsWith('.pdf');

    // Fetch file content from GitHub
    const fileResp = await ghApi(`/repos/${repo}/contents/${encodeURIComponent(filePath).replace(/%2F/g, '/')}?ref=main`);
    if (fileResp.status !== 200) {
      results.errors.push({ file: filePath, error: 'GitHub API fetch failed' });
      continue;
    }

    const fileSha = fileResp.data.sha;
    let textForEmbed;
    let title;

    if (isPdf) {
      const pdfText = extractPdfFromUrl(filePath, repo, GITHUB_TOKEN);
      if (pdfText.includes('extraction failed')) {
        results.errors.push({ file: filePath, error: 'PDF extraction failed' });
      }
      textForEmbed = pdfText;
      title = deriveTitle('', filePath);
    } else {
      textForEmbed = Buffer.from(fileResp.data.content, 'base64').toString('utf8');
      title = deriveTitle(textForEmbed, filePath);
    }

    const hash = contentHash(textForEmbed);

    // Check if this is a personality source file
    if (matchesPersonalitySources(filePath, syncConfig)) {
      personalitySourceChanged = true;
    }

    // Check existing sync_state
    const existingRow = await dbQuery(
      `SELECT qdrant_point_ids FROM sync_state WHERE repo = '${repo.replace(/'/g, "''")}' AND file_path = '${filePath.replace(/'/g, "''")}'`
    );

    let existingQdrantIds = [];
    if (existingRow && existingRow.trim()) {
      existingQdrantIds = existingRow.replace(/[{}]/g, '').split(',').filter(x => x);
    }

    // Delete old Qdrant points
    if (existingQdrantIds.length > 0) {
      await qdrantDelete(existingQdrantIds);
    }

    // Embed and store in Qdrant (chunked)
    const chunks = chunkText(textForEmbed);
    const newQdrantIds = [];

    for (let i = 0; i < chunks.length; i++) {
      const chunkId = uuid();
      const vector = await embed(chunks[i]);
      if (vector) {
        await qdrantUpsert(chunkId, vector, {
          source: 'git_sync',
          agent_id: AGENT_ID,
          repo,
          file_path: filePath,
          title,
          is_pdf: isPdf,
          chunk_index: i,
          total_chunks: chunks.length,
          content: chunks[i].substring(0, 500),
          synced_at: new Date().toISOString()
        });
        newQdrantIds.push(chunkId);
      }
    }

    // Upsert sync_state (no outline_doc_id for git-only files)
    const qdrantIdsArray = `{${newQdrantIds.join(',')}}`;
    const escapedPath = filePath.replace(/'/g, "''");
    const escapedRepo = repo.replace(/'/g, "''");
    await dbQuery(
      `INSERT INTO sync_state (repo, file_path, file_sha, qdrant_point_ids, agent_id, content_hash, is_pdf, sync_origin, sync_lock) VALUES ('${escapedRepo}', '${escapedPath}', '${fileSha}', '${qdrantIdsArray}', '${AGENT_ID}', '${hash}', ${isPdf}, 'github', now()) ON CONFLICT (repo, lower(file_path)) DO UPDATE SET file_sha = '${fileSha}', qdrant_point_ids = '${qdrantIdsArray}', content_hash = '${hash}', is_pdf = ${isPdf}, sync_origin = 'github', sync_lock = now(), last_synced_at = now()`
    );

    results.synced.push({ file: filePath, title, chunks: chunks.length, qdrant_points: newQdrantIds.length, is_pdf: isPdf });
  } catch (e) {
    results.errors.push({ file: filePath, error: 'Processing failed' });
  }
}

// --- Process deleted files ---
for (const filePath of removed) {
  try {
    const existingRow = await dbQuery(
      `SELECT qdrant_point_ids FROM sync_state WHERE repo = '${repo.replace(/'/g, "''")}' AND file_path = '${filePath.replace(/'/g, "''")}'`
    );

    if (existingRow && existingRow.trim()) {
      const qdrantIds = existingRow.replace(/[{}]/g, '').split(',').filter(x => x);

      if (qdrantIds.length > 0) {
        await qdrantDelete(qdrantIds);
      }
      await dbQuery(
        `DELETE FROM sync_state WHERE repo = '${repo.replace(/'/g, "''")}' AND file_path = '${filePath.replace(/'/g, "''")}'`
      );

      if (matchesPersonalitySources(filePath, syncConfig)) {
        personalitySourceChanged = true;
      }

      results.deleted.push({ file: filePath, qdrant_deleted: qdrantIds.length });
    }
  } catch (e) {
    results.errors.push({ file: filePath, error: 'Delete processing failed' });
  }
}

// --- Dynamic Personality Rebuild (driven by sync.yaml personality.sources) ---
if (personalitySourceChanged) {
  try {
    const treeResp = await ghApi(`/repos/${repo}/git/trees/main?recursive=1`);
    if (treeResp.status === 200) {
      const tree = treeResp.data.tree || [];
      const personalityFiles = tree.filter(t => t.type === 'blob' && t.path.endsWith('.md') && matchesPersonalitySources(t.path, syncConfig));

      // Categorize files using priority_order from sync.yaml
      const categories = {};
      for (const cat of syncConfig.personality.priority_order) {
        categories[cat] = [];
      }
      if (!categories['Other']) categories['Other'] = [];

      for (const pf of personalityFiles) {
        const ctxResp = await ghApi(`/repos/${repo}/contents/${encodeURIComponent(pf.path).replace(/%2F/g, '/')}?ref=main`);
        if (ctxResp.status === 200) {
          const text = Buffer.from(ctxResp.data.content, 'base64').toString('utf8');
          const relativePath = pf.path.replace(/^AI\/LLM Context\//, '');
          const topDir = relativePath.split('/')[0];

          let matched = false;
          for (const cat of Object.keys(categories)) {
            if (cat !== 'Other' && topDir.toLowerCase().includes(cat.toLowerCase())) {
              categories[cat].push({ path: relativePath, text });
              matched = true;
              break;
            }
          }
          if (!matched) {
            categories['Other'].push({ path: relativePath, text });
          }
        }
      }

      // Build structured context with category headers
      const maxContextChars = syncConfig.personality.max_context_chars || 50000;
      let contextContent = '';
      const priorityOrder = syncConfig.personality.priority_order.length > 0 ? syncConfig.personality.priority_order : ['Communication', 'Frameworks', 'Products', 'Competitors', 'Workflows', 'Templates', 'Other', 'Skills'];

      for (const cat of priorityOrder) {
        const files = categories[cat];
        if (!files || files.length === 0) continue;

        let section = `\n\n## ${cat.toUpperCase()}\n`;
        for (const f of files) {
          section += `\n### ${f.path}\n${f.text}\n`;
        }

        if (contextContent.length + section.length <= maxContextChars) {
          contextContent += section;
        } else {
          const remaining = maxContextChars - contextContent.length;
          if (remaining > 200) {
            contextContent += section.substring(0, remaining);
          }
          break;
        }
      }

      if (contextContent.length > 100) {
        const [loadedRebuildPrompt, loadedEngineerPrompt] = await Promise.all([
          loadPrompt('sync:personality-rebuild'),
          loadPrompt('sync:prompt-engineer')
        ]);

        let userPromptText;
        if (loadedRebuildPrompt) {
          userPromptText = loadedRebuildPrompt.replace('{{agentName}}', 'PM Assistant PM').replace('{{contextDocuments}}', contextContent);
        } else {
          userPromptText = `Based on the following context documents for a Product Management AI assistant, generate a detailed personality prompt (2500-3500 characters).\n\nThe assistant is called "PM Assistant PM" and helps with product management for the PM Assistant project.\n\nExtract: behavioral guidelines, methodology, tone, key frameworks, competitive landscape, and specific instructions for common PM tasks.\n\nContext documents:\n${contextContent}`;
        }

        const sysPromptText = loadedEngineerPrompt || 'You are an expert prompt engineer specializing in AI assistant system prompts. Generate a system prompt for a Product Management AI assistant. Output ONLY the system prompt text, nothing else. Target 2500-3500 characters.';

        const personality = await llmCall(userPromptText, sysPromptText);

        if (personality && personality.length > 50) {
          const versionRow = await dbQuery(
            "SELECT COALESCE(MAX(version), 0) FROM personality WHERE name = 'pm-assistant'"
          );
          const newVersion = parseInt(versionRow || '0') + 1;

          await dbQuery("UPDATE personality SET active = false WHERE name = 'pm-assistant'");
          const escapedPrompt = personality.replace(/'/g, "''");
          await dbQuery(
            `INSERT INTO personality (name, version, system_prompt, traits, active) VALUES ('pm-assistant', ${newVersion}, '${escapedPrompt}', '{"tone": "professional", "domain": "product-management", "auto_generated": true}'::jsonb, true)`
          );

          results.personality_rebuilt = true;
        }
      }
    }
  } catch (e) {
    results.errors.push({ file: 'personality_rebuild', error: 'Personality rebuild failed' });
  }
}

await dbQuery("DELETE FROM execution_locks WHERE workflow_id = 19");
return [{ json: {
  success: true,
  mode,
  repo,
  synced: results.synced.length,
  deleted: results.deleted.length,
  skipped_no_match: results.skipped_no_match.length,
  errors: results.errors.length,
  personality_rebuilt: results.personality_rebuilt,
  details: results
} }];

